function listing(
  id: string,
  title: string,
  mlsNumber: string,
  price: number,
  verified: boolean,
): CiteProperty {
  return {
    id,
    title,
    address: title,
    neighborhood: id === "coastal" ? "Solana Beach" : id === "grove" ? "North Broadway" : "Rancho Bernardo",
    city: id === "coastal" ? "Solana Beach" : id === "grove" ? "Escondido" : "San Diego",
    price,
    beds: 4,
    baths: 4,
    sqft: 3_000,
    yearBuilt: 2000,
    type: "house",
    status: "active",
    daysOnMarket: 10,
    features: [],
    description: `Public listing fixture for ${title}.`,
    lat: 0,
    lng: 0,
    pricePerSqft: 0,
    estimatedValue: price,
    accent: "#5b8def",
    pattern: 1,
    mlsNumber,
    listingSide: "mine",
    listAgentName: "San Diego Pilot Agent",
    source: {
      kind: verified ? "mls" : "website",
      provider: verified ? "SDMLS fixture" : "Agent website fixture",
      url: `https://listings.example/${id}`,
      observedAt: verified ? "2026-08-18T12:00:00.000-07:00" : "2026-07-01T12:00:00.000-07:00",
      evidenceLevel: verified ? "provider_verified" : "site_published",
      trust: verified ? "server_attested" : undefined,
      attestationId: verified ? `pilot-attestation:${mlsNumber}` : undefined,
    },
    representation: verified
      ? {
          role: "listing",
          matchedAgentId: "PILOT123",
          matchedAgentName: "San Diego Pilot Agent",
          verifiedAt: "2026-08-18T12:00:00.000-07:00",
        }
      : { role: "unknown" },
    visibility: "public",
    transactionType: id === "lease-conflict" ? "lease" : "sale",
    pricePeriod: id === "lease-conflict" ? "month" : "total",
  };
}

